using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo.Variables;

[CreateAssetMenu(menuName = "Variables References/Color Reference")]
public class ColorReference : ScriptableObject
{
	[Header("Variable")]
	[SerializeField]
	private bool externalSet;

	[SerializeField]
	[HideIf("externalSet")]
	private Color value;

	public Color Value => value;

	public void SetExternalSet(bool value)
	{
		externalSet = value;
	}

	public void SetValue(Color value)
	{
		if (externalSet)
		{
			Debug.LogFormat("Setting ColorReference Value to {0}", value);
			this.value = value;
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}
}
